'use strict';
const $=s=>document.querySelector(s), cats=['资料总览','Nexus综述','前沿文献','研究方法','数据资源','现实案例','政策报告'],icons=['◫','▤','⌕','⌘','▦','◎','▧'];let data=[],notes=[],policyScope='全部政策',category='资料总览',favorites=false;
const read=(key,defaultValue)=>{try{return JSON.parse(localStorage.getItem(key))||defaultValue}catch{return defaultValue}};let stars=new Set(read('frank-stars',[]));const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const url=x=>{try{const u=new URL(x);return ['https:','http:'].includes(u.protocol)?u.href:'#'}catch{return '#'}};const all=()=>data;
function download(){const b=new Blob([JSON.stringify(all(),null,2)],{type:'application/json'}),u=URL.createObjectURL(b),a=document.createElement('a');a.href=u;a.download='catalog.json';a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)}
function render(){const a=all();$('#nav').innerHTML=cats.map((c,i)=>`<button data-cat="${c}" class="${c===category?'active':''}"><span>${icons[i]}</span>${c}<small>${c==='资料总览'?a.length:c==='Nexus综述'?notes.length:a.filter(x=>x.categories.includes(c)).length}</small></button>`).join('');$('#chips').innerHTML=cats.filter(c=>c!=='Nexus综述').map(c=>`<button data-cat="${c}" class="${c===category?'active':''}">${c==='资料总览'?'全部资料':c}</button>`).join('');$('#crumb').textContent=category;$('#heading').textContent=favorites?'我的收藏':category==='资料总览'?'研究资料':category;$('#stats').innerHTML=[['收录文献',a.filter(x=>x.categories.some(c=>['前沿文献','研究方法'].includes(c))).length],['方法文献',a.filter(x=>x.categories.includes('研究方法')).length],['开放数据入口',a.filter(x=>x.categories.includes('数据资源')).length],['主题方向',4]].map(([t,n])=>`<div class="stat"><strong>${n}<span> / </span></strong><span>${t}</span></div>`).join('');$('#policy-filters').hidden=category!=='政策报告';document.querySelectorAll('[data-scope]').forEach(b=>b.classList.toggle('active',b.dataset.scope===policyScope));const q=$('#search').value.toLowerCase(),topic=$('#topic').value;
if(category==='Nexus综述'){const n=notes.filter(p=>JSON.stringify(p).toLowerCase().includes(q));$('#count').textContent=`${notes.length} 个 Part · ${notes.reduce((a,p)=>a+p.chapters.length,0)} 章`;$('#results').innerHTML=n.map(p=>`<article class="card part-card"><div class="meta">NEXUS REVIEW</div><h3><a href="reviews/${esc(p.id)}.html">${esc(p.title)}</a></h3><div class="chapter-list">${p.chapters.map(c=>`<a href="reviews/${esc(c.id)}.html"><span>第 ${c.number} 章</span><strong>${esc(c.title)}</strong><small>${c.sections.length} 节 ↗</small></a>`).join('')}</div><div class="cardbottom"><a href="reviews/${esc(p.id)}.html">浏览本 Part ↗</a></div></article>`).join('')||'<p class="empty">没有找到相关章节。</p>';return}

let list=a.filter(x=>(category!=='政策报告'||policyScope==='全部政策'||x.scope===policyScope)&&(category==='资料总览'||x.categories.includes(category))&&(!favorites||stars.has(x.id))&&(topic==='全部主题'||x.tags.includes(topic))&&JSON.stringify([x.title,x.summary,x.method,x.journal,x.tags,x.year,x.analysis,x.abstract?.text]).toLowerCase().includes(q));if($('#sort').value!=='default')list.sort((a,b)=>$('#sort').value==='new'?b.year-a.year:a.year-b.year);$('#count').textContent=`${list.length} 条资料`;$('#results').innerHTML=list.length?list.map(x=>`<article class="card"><button class="star" data-star="${esc(x.id)}" aria-label="收藏 ${esc(x.title)}" aria-pressed="${stars.has(x.id)}">${stars.has(x.id)?'★':'☆'}</button><div class="meta"><span class="badge">${esc(x.categories.join(' · '))}</span><span>${x.year||'资源入口'}</span></div><h3>${esc(x.title)}</h3>${x.abstract?.text?`<details class="abstract" open><summary>摘要 · ${esc(x.abstract.kind||'中文概述')}</summary><p>${esc(x.abstract.text)}</p></details>`:`<p>${esc(x.summary)}</p>`}<div>${x.tags.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="journal">${esc(x.journal)}</div><div class="cardbottom"><button data-detail="${esc(x.id)}">查看导读 ↗</button><a href="${esc(url(x.url))}" target="_blank" rel="noopener noreferrer">官方来源 ↗</a></div></article>`).join(''):'<p class="empty">没有找到匹配的资料。试试其他关键词或主题。</p>'}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.scope){policyScope=b.dataset.scope;render()}if(b.dataset.cat){category=b.dataset.cat;favorites=false;render()}if(b.dataset.star){stars.has(b.dataset.star)?stars.delete(b.dataset.star):stars.add(b.dataset.star);localStorage.setItem('frank-stars',JSON.stringify([...stars]));render()}if(b.dataset.detail){const x=all().find(x=>x.id===b.dataset.detail);$('#detailbody').innerHTML=`<p class="eyebrow">${esc(x.id)} · ${esc(x.categories.join(' / '))}</p><h2>${esc(x.title)}</h2><p>${esc(x.journal)} ${x.year||''}</p>${x.abstract?.text?`<section class="abstract-full"><h3>摘要 · ${esc(x.abstract.kind||'中文概述')}</h3><p>${esc(x.abstract.text)}</p></section>`:''}${x.analysis?Object.entries({background:'研究背景',methods:'研究方法',conclusions:'主要结论',implications:'研究启示'}).map(([k,t])=>`<section class="analysis-section"><h3>${t}</h3><p>${esc(x.analysis[k])}</p></section>`).join(''):`<h3>资料导读</h3><div class="reading">${esc(x.summary)}</div>`}${x.scope?`<p>政策范围：${esc(x.scope)}</p>`:''}${x.id.startsWith('L')?`<p><a href="literature/${esc(x.id)}.html">打开独立精读页面 ↗</a></p>`:''}<a class="primary" href="${esc(url(x.url))}" target="_blank" rel="noopener noreferrer">访问官方来源 ↗</a>`;$('#detail').showModal()}if(b.classList.contains('close'))b.closest('dialog').close()});
$('#saved').onclick=()=>{favorites=!favorites;category='资料总览';render()};$('#export').onclick=download;for(const id of ['search','topic','sort'])$('#'+id).addEventListener(id==='search'?'input':'change',render);

Promise.all([fetch('catalog.json').then(r=>{if(!r.ok)throw Error('目录加载失败');return r.json()}),fetch('reviews.json').then(r=>r.json())]).then(([a,n])=>{data=a;notes=n;render()}).catch(e=>{$('#results').innerHTML=`<p class="empty">${esc(e.message)}。请通过网站服务器访问，避免直接双击 HTML。</p>`});
